CREATE DATABASE IF NOT EXISTS LittleLemonDB;
USE LittleLemonDB;
CREATE TABLE IF NOT EXISTS Customers (CustomerID INT PRIMARY KEY AUTO_INCREMENT, CustomerName VARCHAR(100) NOT NULL, Email VARCHAR(120) UNIQUE, Phone VARCHAR(30));
CREATE TABLE IF NOT EXISTS Bookings (BookingID INT PRIMARY KEY AUTO_INCREMENT, BookingDate DATE NOT NULL, BookingTime TIME NOT NULL, TableNumber INT NOT NULL, CustomerID INT NOT NULL, GuestCount INT NOT NULL DEFAULT 2, BookingStatus VARCHAR(20) NOT NULL DEFAULT 'Confirmed', FOREIGN KEY(CustomerID) REFERENCES Customers(CustomerID), UNIQUE(BookingDate, BookingTime, TableNumber));
CREATE TABLE IF NOT EXISTS MenuItems (MenuItemID INT PRIMARY KEY AUTO_INCREMENT, ItemName VARCHAR(100) NOT NULL, Category VARCHAR(40) NOT NULL, Price DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS Orders (OrderID INT PRIMARY KEY AUTO_INCREMENT, CustomerID INT NOT NULL, BookingID INT NULL, OrderDate DATE NOT NULL, OrderStatus VARCHAR(25) NOT NULL DEFAULT 'Completed', FOREIGN KEY(CustomerID) REFERENCES Customers(CustomerID), FOREIGN KEY(BookingID) REFERENCES Bookings(BookingID));
CREATE TABLE IF NOT EXISTS OrderItems (OrderItemID INT PRIMARY KEY AUTO_INCREMENT, OrderID INT NOT NULL, MenuItemID INT NOT NULL, Quantity INT NOT NULL, UnitPrice DECIMAL(10,2) NOT NULL, FOREIGN KEY(OrderID) REFERENCES Orders(OrderID), FOREIGN KEY(MenuItemID) REFERENCES MenuItems(MenuItemID));
